import{_ as t,o as a,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-02-01","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-02-01","date":"2022-02-01T00:00:00.000Z","updated":"2022-02-02T00:00:00.000Z","tags":["Ceph","Orchestrator","Distributed Storage","Documentation","NFS Manager"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-02-01.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-02-01.md","lastUpdated":1780460162000}'),i={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-02-01.md"};function o(n,e,s,h,c,d){return a(),r("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>日期</strong>: 2022-02-01</li><li><strong>参会人员</strong>: [参会人员名单]</li><li><strong>主持人</strong>: [主持人姓名]</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>文档更新</strong></p><ul><li>讨论了在文档中记录每个功能的引入时间、版本和贡献者的必要性。</li><li>决定开始在新功能引入时添加文档注释，以便追踪功能的历史和来源。</li></ul></li><li><p><strong>NFS Manager模块的使用</strong></p><ul><li>讨论了在不启用Orchestration模块的情况下使用NFS Manager模块。</li><li>确定了Rook团队的需求，他们希望在无需依赖Orchestration模块的情况下管理NFS导出。</li><li>提出了两种解决方案：添加新的命令（如<code>nfs cluster register</code>和<code>unregister</code>）或使用现有命令并添加一个选项（如<code>--no-orchestration</code>）。</li><li>最终决定简化流程，只移除导出命令对Orchestration模块的依赖，并处理集群ID验证。</li></ul></li><li><p><strong>自然排序问题</strong></p><ul><li>讨论了在某些命令中使用自然排序（如<code>ceph osd tree</code>）以提高用户体验。</li><li>决定在所有相关命令中一致地使用自然排序，以保持命令输出的一致性。</li><li>考虑引入外部Python包<code>natsort</code>来实现自然排序。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>将在新功能引入时添加文档注释。</li><li>简化NFS Manager模块的使用流程，移除对Orchestration模块的依赖。</li><li>在所有相关命令中一致地使用自然排序，并考虑引入<code>natsort</code>包。</li></ul><h4 id="后续的行动计划" tabindex="-1">后续的行动计划 <a class="header-anchor" href="#后续的行动计划" aria-label="Permalink to &quot;后续的行动计划&quot;">​</a></h4><ul><li>完成NFS Manager模块的代码调整，预计本周内提交PR。</li><li>引入<code>natsort</code>包并实现自然排序，为相关命令创建单独的PR和问题跟踪。</li><li>确认CentOS容器问题的修复情况。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>确认CentOS容器问题的修复情况，目前问题已解决。</li></ul><h4 id="下次会议" tabindex="-1">下次会议 <a class="header-anchor" href="#下次会议" aria-label="Permalink to &quot;下次会议&quot;">​</a></h4><ul><li>下次会议预定于[具体日期]举行。</li></ul>',13)])])}const p=t(i,[["render",o]]);export{_ as __pageData,p as default};
